import {RadialSPH} from './radial-sph.js';
import {RadialFV} from './radial-fv.js';
import {startupProfile,steadyProfile,referenceMean,referenceFRe} from './radial-reference.js';
import {PIPE} from './physics.js';
const $=id=>document.getElementById(id), KEYS=['sph','fixed','amr','moving'];
const C={grid:'#e7eeee',ink:'#38566a',muted:'#7c8e96',orange:'#e58146',teal:'#0b8994'};
let models={},costs={},currentTime=0,targetTime=.25,resolution=32,re=1000,running=false,callbackActive=false;
const fmt=(v,d=3)=>Number.isFinite(v)?v.toFixed(d):'—';
window.methodLab={get models(){return models},get time(){return currentTime},get running(){return running},get resolution(){return resolution},get re(){return re}};
function setup(){models={sph:new RadialSPH({particles:resolution}),fixed:new RadialFV({method:'fixed',cells:resolution}),amr:new RadialFV({method:'amr',cells:resolution}),moving:new RadialFV({method:'moving',cells:resolution})};costs=Object.fromEntries(KEYS.map(k=>[k,0]));currentTime=0;$('benchError').hidden=true;render()}
function fit(canvas){const b=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.max(1,b.width),h=Math.max(1,b.height);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);return {c,w,h}}
function path(c,points,color,width=2,dash=[]){c.beginPath();for(let i=0;i<points.length;i++){const [x,y]=points[i];if(i)c.lineTo(x,y);else c.moveTo(x,y)}c.strokeStyle=color;c.lineWidth=width;c.setLineDash(dash);c.stroke();c.setLineDash([])}
function curve(key,samples,reference){const {c,w,h}=fit($(key+'Profile')),l=37,r=w-15,t=23,b=h-35,X=q=>l+q*(r-l),Y=u=>b-u/2.2*(b-t);c.font='10px -apple-system,sans-serif';c.fillStyle=C.muted;c.textAlign='left';c.fillText('軸方向速度 u/U目標',l,11);for(const v of [0,1,2]){path(c,[[l,Y(v)],[r,Y(v)]],C.grid,.8);c.textAlign='right';c.fillText(String(v),l-7,Y(v)+3)}for(const v of [0,.5,1]){path(c,[[X(v),t],[X(v),b]],C.grid,.8);c.textAlign=v===0?'left':v===1?'right':'center';c.fillText(v===0?'0 中心':v===1?'1 壁':'0.5',X(v),b+16)}c.textAlign='right';c.fillText('半径 r/R →',r,h-3);path(c,reference.steady.map(a=>[X(a.r),Y(a.u)]),'#a7b9be',1.4,[4,4]);path(c,reference.transient.map(a=>[X(a.r),Y(a.u)]),C.ink,2);for(const p of samples){c.fillStyle=C.orange;c.beginPath();c.arc(X(p.r),Y(p.u),2.5,0,Math.PI*2);c.fill()}}
function drawMesh(key,model,samples){const {c,w}=fit($(key+'Mesh')),l=10,r=w-10,yt=16,ht=18;c.fillStyle='#eef5f2';c.fillRect(l,yt,r-l,ht);c.font='9px -apple-system,sans-serif';c.fillStyle=C.muted;c.textAlign='left';c.fillText(key==='sph'?'粒子位置（半径方向）':'セル境界（半径方向）',l,9);if(key==='sph'){for(const p of samples){c.fillStyle=C.teal;c.beginPath();c.arc(l+p.r*(r-l),yt+ht/2,2,0,Math.PI*2);c.fill()}}else{const mesh=model.mesh();for(let i=0;i<mesh.length-1;i++){const a=mesh[i],b=mesh[i+1];c.fillStyle=i%2?'#d6e9e4':'#edf4f0';c.fillRect(l+a*(r-l),yt,(b-a)*(r-l),ht)}c.strokeStyle='#7aa9a8';c.lineWidth=.7;for(const q of mesh){c.beginPath();c.moveTo(l+q*(r-l),yt);c.lineTo(l+q*(r-l),yt+ht);c.stroke()}}c.fillStyle=C.muted;c.textAlign='left';c.fillText('中心',l,47);c.textAlign='right';c.fillText('壁',r,47)}
function referenceCell(a,b,time){const mid=(a*a+b*b)/2,half=(b*b-a*a)/2,offset=half/Math.sqrt(3);return .5*(startupProfile(Math.sqrt(Math.max(0,mid-offset)),time)+startupProfile(Math.sqrt(mid+offset),time))}
function numericalError(key,model,samples){if(currentTime===0)return 0;const faces=key==='sph'?null:model.mesh();let numerator=0,denominator=0;for(let i=0;i<samples.length;i++){const p=samples[i],ref=faces?referenceCell(faces[i],faces[i+1],currentTime):startupProfile(p.r,currentTime),weight=p.weight??1;numerator+=weight*(p.u-ref)**2;denominator+=weight*ref*ref}return Math.sqrt(numerator/Math.max(denominator,1e-30))}
function metrics(key,model,samples){const d=model.diagnostics(),values=[['同時刻の解析解との差',fmt(numericalError(key,model,samples)*100,3)+'%'],['壁面係数 fD Re実',d.fRe===null?'—':fmt(d.fRe,2)],['計算時間（累積）',fmt(costs[key],1)+' ms']];const el=$(key+'Metrics');el.replaceChildren();for(const [label,value] of values){const a=document.createElement('div'),span=document.createElement('span'),b=document.createElement('b');span.textContent=label;b.textContent=value;a.append(span,b);el.append(a)}$(key+'Count').textContent=`${d.count} ${key==='sph'?'粒子':'セル'}`}
function render(){const reference={steady:[],transient:[]};for(let i=0;i<=120;i++){const r=i/120;reference.steady.push({r,u:steadyProfile(r)});reference.transient.push({r,u:startupProfile(r,currentTime)})}for(const key of KEYS){const sample=models[key].sample();curve(key,sample,reference);drawMesh(key,models[key],sample);metrics(key,models[key],sample)}$('benchCurrentTime').textContent=fmt(currentTime,3);$('benchPhysicalTime').innerHTML=`${fmt(currentTime*(PIPE.D/2)**2/PIPE.nu,1)} <small>s</small>`;$('benchMean').textContent=fmt(referenceMean(currentTime),4);const fre=referenceFRe(currentTime);$('benchFriction').textContent=fre===null?'—':fmt(fre,2)}
function status(){const targetU=re*PIPE.nu/PIPE.D;$('benchStatus').textContent=`${running?'比較を計算中':currentTime>=targetTime-1e-12?'比較完了':'比較を停止'} · 共通時刻 θ=${fmt(currentTime,3)} / ${fmt(targetTime,2)} · U目標=${fmt(targetU,4)} m/s · 壁面係数は始動中の値です。定常化すると64へ近づきます。`;$('benchPause').textContent=running?'Ⅱ 一時停止':'▶ 再開'}
function advance(){callbackActive=false;if(!running)return;try{let steps=0;const frameStart=performance.now(),frameTarget=Math.min(targetTime,currentTime+.02),externalStep=.002*(16/resolution)**2;while(currentTime<frameTarget-1e-12&&(steps===0||performance.now()-frameStart<16)){const ds=Math.min(externalStep,frameTarget-currentTime,targetTime-currentTime);for(const key of KEYS){const t=performance.now();models[key].step(ds);costs[key]+=performance.now()-t}currentTime=Math.min(targetTime,currentTime+ds);steps++}render();if(currentTime>=targetTime-1e-12)running=false;status();if(running)schedule()}catch(e){running=false;$('benchError').hidden=false;$('benchError').textContent=e.message;status();console.error(e)}}
function schedule(){if(callbackActive)return;callbackActive=true;requestAnimationFrame(advance)}
function start(){try{resolution=Number($('benchResolution').value);re=Number($('benchRe').value);targetTime=Number($('benchTime').value);if(![16,32,64].includes(resolution)||!Number.isFinite(targetTime)||targetTime<.01||targetTime>2)throw new Error('条件を確認してください。');setup();running=true;status();schedule()}catch(e){running=false;$('benchError').hidden=false;$('benchError').textContent=e.message}}
$('benchCsv').addEventListener('click',()=>{const rows=[['method','viscous_time_theta','reference_Re_target','base_resolution','actual_elements','mean_u_over_U_target','wall_fD_Re_actual','relative_L2_error','computation_ms','note']];for(const key of KEYS){const d=models[key].diagnostics();rows.push([key,currentTime,re,resolution,d.count,d.meanU,d.fRe===null?'':d.fRe,numericalError(key,models[key],models[key].sample()),costs[key],'1D axisymmetric laminar benchmark; not 3D turbulence'])}const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(row=>row.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='pipe-method-comparison.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)});
$('benchRun').addEventListener('click',start);$('benchTime').addEventListener('input',()=>{$('benchTimeValue').textContent=Number($('benchTime').value).toFixed(2)});$('benchPause').addEventListener('click',()=>{if(running)running=false;else if(currentTime<targetTime){running=true;schedule()}status()});$('benchReset').addEventListener('click',()=>{running=false;setup();status()});window.addEventListener('resize',()=>render());
start();
